"""Investment Analysis chapters 2 to 4: Fixed Income, Equity Valuation, Portfolio Management.

Original exam-style material written for FinLearn. Not affiliated with or endorsed by CFA Institute.
Every number is recomputed in backend/tests/check_ia_math.py.
"""
from seed_data import _id, _intro, _teach, _example, _flash, _mcq, _concept
from seed_finance import _choice, _outcome


def _chapter(course_id, order, title, description, module_title):
    ch_id, m_id = _id(), _id()
    ch = {"id": ch_id, "course_id": course_id, "order": order, "title": title, "description": description}
    m = {"id": m_id, "chapter_id": ch_id, "order": 1, "title": module_title}
    return ch, m, m_id


# ---------------------------------------------------------------------------
# CHAPTER 2: FIXED INCOME
# ---------------------------------------------------------------------------

def fixed_income_chapter(course_id):
    ch, m, m_id = _chapter(course_id, 2, "Fixed Income",
                           "Bond pricing, yield, duration and credit risk: how to value an IOU and what makes its price move.", "Bonds")

    c1 = _concept(m_id, 1,
        "Bond pricing and yield",
        "Price a bond as the present value of its cash flows and explain why price and yield move in opposite directions.",
        "A bond is a loan you make to a government or company. In return you get regular coupon payments and your principal back at maturity. "
        "Its price is simply the present value of those payments, discounted at the yield the market demands today.",
        "A ₹1,000 bond pays an 8% coupon for 5 years. If the market wants a 10% yield, the bond is worth about ₹924.",
        ["Price = PV of coupons + PV of the principal, discounted at the yield to maturity (YTM).",
         "Price and yield move in opposite directions.",
         "Coupon below YTM gives a discount price. Coupon above YTM gives a premium. Equal gives par.",
         "Current yield = annual coupon ÷ price."],
        ["Forgetting to discount the principal.",
         "Thinking a higher coupon always means a higher price regardless of the market yield.",
         "Confusing the coupon rate with the yield to maturity."],
        [
            _intro("An IOU with a price", "You lend ₹1,000 and are promised ₹80 every year for five years, plus your ₹1,000 back. What is that promise worth today? It depends on what return investors demand right now."),
            _teach("Pricing a bond",
                   "A bond's cash flows are known: coupon payments each period and the face value at maturity. Its price is their present value at the yield to maturity (YTM): Price = Σ C ÷ (1 + y)^t + Face ÷ (1 + y)^n. If the coupon rate equals the YTM, the bond trades at par. If the YTM is above the coupon rate, the price falls below par (a discount) so the buyer earns the extra yield through the price rising back to par. If the YTM is below the coupon rate, the price is above par (a premium). A zero-coupon bond pays only the face value: Price = Face ÷ (1 + y)^n.",
                   ["Price = PV of coupons + PV of face value", "YTM above coupon: discount. YTM below coupon: premium", "Zero-coupon: Face ÷ (1 + y)^n"]),
            _example("The 8% bond in a 10% market",
                     "A ₹1,000 bond pays an 8% annual coupon (₹80) for 5 years and the market yield is 10%. The coupons are worth 80 × 3.7908 = ₹303.26 today (the 5-year annuity factor at 10% is 3.7908), and the ₹1,000 principal is worth 1,000 ÷ 1.10^5 = ₹620.92. The price is ₹924.18, a discount to par. The current yield is 80 ÷ 924.18 = 8.66%.",
                     "A bond paying less than the market demands must sell for less than its face value."),
            _flash("If market yields rise, what happens to the price of an existing bond?", "It falls. Price and yield move in opposite directions."),
            _choice("An investor holds the ₹1,000, 8% five-year bond that is priced at ₹924.18 to yield 10%. The next month, market yields for similar bonds fall to 6%.",
                    "What happens to the price of the bond she holds?",
                    [("It stays at ₹924.18, because the coupon and maturity have not changed", "bad",
                      "The cash flows are fixed, but their present value depends on the yield. When the required yield falls, the same payments are worth more.",
                      _outcome(("Price at 10% yield", 924), ("Price at 6% yield", 1084), "At 6%: 80 × 4.2124 + 1,000 ÷ 1.06^5 = ₹336.99 + ₹747.26 = ₹1,084.25.")),
                     ("It rises to about ₹1,084, a premium, because an 8% coupon is now attractive", "good",
                      "Correct. An 8% coupon is worth more when new bonds only offer 6%. Discounting the same cash flows at 6% gives about ₹1,084.25.",
                      _outcome(("Price at 10% yield", 924), ("Price at 6% yield", 1084), "Yield down 4 points, price up about 17%.")),
                     ("It falls, because lower yields mean worse news", "bad",
                      "When the required yield falls, the same cash flows are discounted at a lower rate, so their present value, and the price, rises.")]),
            _teach("Current yield, YTM and par",
                   "Current yield is just annual coupon ÷ price. It ignores the gain or loss as the price moves to par at maturity, so it is not the full return. The yield to maturity is the single discount rate that makes the present value of all cash flows equal the price, and it is the standard yield measure. A bond bought at a discount earns a YTM above its current yield, because it also gains as the price pulls up to par. For a zero-coupon bond with 3 years left and a 7% yield, the price is 1,000 ÷ 1.07^3 = ₹816.30.",
                   ["Current yield = coupon ÷ price", "YTM includes the pull to par", "Discount bond: YTM > current yield > coupon rate"]),
            _choice("A ₹1,000 bond with an 8% coupon sells for ₹924.18. Another trader says, 'This bond yields 8.66%, so that is my return if I hold to maturity.'",
                    "Is 8.66% the return from holding to maturity?",
                    [("Yes, 8.66% is the yield to maturity", "bad",
                      "8.66% is the current yield (coupon ÷ price). It ignores the ₹75.82 gain as the price climbs back to ₹1,000 at maturity."),
                     ("No. The holder also gains as the price rises to par, so the yield to maturity, 10%, is higher", "good",
                      "Correct. Current yield only counts the coupon. At 10% the present value of coupons plus principal equals the ₹924.18 price, so 10% is the yield to maturity.")]),
            _mcq("A bond with a 6% coupon trades when market yields for similar bonds are 8%. How does its price compare with par?",
                 ["Above par (premium)", "Below par (discount)", "Exactly par", "It cannot be determined"], 1,
                 "The coupon is below the market yield, so the bond must trade at a discount to offer buyers the market return."),
            _mcq("What is the price of a ₹1,000 zero-coupon bond with 3 years to maturity when the yield is 7%?",
                 ["₹790.00", "₹816.30", "₹870.00", "₹1,000"], 1,
                 "Price = 1,000 ÷ 1.07^3 = 1,000 ÷ 1.225043 = ₹816.30."),
        ], xp=30)

    c2 = _concept(m_id, 2,
        "Duration and interest-rate risk",
        "Use duration to estimate how much a bond's price changes when yields change, and explain what drives it.",
        "Duration measures how sensitive a bond's price is to a change in interest rates. A bond with a modified duration of 4 will lose about 4% "
        "of its price if yields rise by 1 percentage point.",
        "A 5-year zero-coupon bond has a modified duration of about 4.63. If yields rise 1%, its price falls about 4.6%.",
        ["Price change ≈ −modified duration × change in yield.",
         "Modified duration = Macaulay duration ÷ (1 + y).",
         "Longer maturity and lower coupon mean higher duration.",
         "Duration is a linear estimate. It slightly overstates the fall and understates the rise, a gap called convexity."],
        ["Treating duration as a time in years only.",
         "Assuming price falls and rises by exactly the same amount for equal yield moves.",
         "Ignoring that long, low-coupon bonds are the most sensitive."],
        [
            _intro("How far will it fall?", "Rates rise by 1 percentage point. Will your bond lose 1%, 5% or 10%? The answer is one number, and it is called duration."),
            _teach("Macaulay and modified duration",
                   "Macaulay duration is the weighted average time, in years, to receive a bond's cash flows, with each payment weighted by its present value. A zero-coupon bond's Macaulay duration equals its maturity. Modified duration = Macaulay duration ÷ (1 + y) and converts that into price sensitivity: % change in price ≈ −modified duration × Δy. Higher coupons return cash sooner, which lowers duration. Longer maturities raise it. So a long-term, low-coupon bond is the most sensitive to interest rates.",
                   ["% price change ≈ −modified duration × Δy", "Zero-coupon: Macaulay duration = maturity", "Longer maturity and lower coupon: higher duration"]),
            _example("A 5-year zero-coupon bond",
                     "A 5-year zero-coupon bond yields 8%. Its Macaulay duration is 5 years, so its modified duration is 5 ÷ 1.08 = 4.63. If the yield rises by 1 percentage point, the estimated price fall is 4.63%. The actual prices are ₹680.58 at 8% and ₹649.93 at 9%, a fall of 4.50%. The estimate is close but a touch too large for a rise in yield.",
                     "Duration is a good first estimate, but not exact, because the price-yield relationship is curved."),
            _flash("What does a modified duration of 6 mean?", "The bond's price falls by about 6% when yields rise by 1 percentage point (and rises by about 6% when yields fall by 1)."),
            _choice("A fund manager expects interest rates to rise sharply over the next year. She can hold a 2-year bond or a 10-year bond with the same 6% coupon, both priced at par.",
                    "Which bond should she hold to limit losses if she is right?",
                    [("The 10-year bond, because it pays interest for longer", "bad",
                      "Longer maturity means a higher duration (about 7.4 for the 10-year at par), so it would lose much more when yields rise.",
                      _outcome(("Modified duration of the 2-year (approx)", 1.8), ("Modified duration of the 10-year (approx)", 7.4), "A 1% rise in yields costs about 1.8% on the 2-year and about 7.4% on the 10-year.")),
                     ("The 2-year bond, because its much lower duration (about 1.8) means a smaller price fall", "good",
                      "Correct. Short bonds have low duration, so a rise in yields hurts them much less. She gives up some yield, but protects capital.",
                      _outcome(("Modified duration of the 2-year (approx)", 1.8), ("Modified duration of the 10-year (approx)", 7.4), "Roughly four times less sensitive to the same rate move.")),
                     ("They are the same, since both have a 6% coupon", "bad", "The same coupon does not mean the same sensitivity. Maturity is a major driver of duration.")]),
            _teach("Where duration falls short",
                   "Duration assumes a straight-line link between price and yield, but the true relationship is curved. This curvature is called convexity. Because of convexity, for a given size of yield change a bond gains more when yields fall than it loses when they rise, so duration slightly overstates the fall and understates the rise. For small yield changes the error is tiny, and for large changes it matters. Duration also assumes a parallel shift in yields and ignores the credit quality changing.",
                   ["Convexity: price-yield curve is curved", "Duration is accurate for small moves", "It assumes a parallel shift in yields"]),
            _choice("A ₹1,000 bond with a 8% coupon has a modified duration of about 3.89 at a 10% yield. Yields rise 1 percentage point to 11%.",
                    "What price change does duration predict, and what is roughly true of the actual change?",
                    [("Duration predicts a fall of about 3.9%. The actual fall is about 3.8%, slightly less, because of convexity", "good",
                      "Correct. The estimate −3.89 × 1% = −3.89%. The exact price falls from ₹924.18 to about ₹889.1, which is −3.79%. The linear estimate overstates the fall slightly."),
                     ("Duration predicts a rise, because higher yields mean higher income", "bad",
                      "Higher yields lower the present value of fixed cash flows, so the price falls."),
                     ("Duration predicts no change, as coupons are fixed", "bad",
                      "Fixed coupons do not mean a fixed price. Price changes when the discount rate changes.")]),
            _mcq("A bond has a modified duration of 5. Yields rise by 0.5 percentage points. What is the approximate price change?",
                 ["−0.5%", "−2.5%", "−5%", "+2.5%"], 1,
                 "Change ≈ −5 × 0.5% = −2.5%."),
            _mcq("Which bond has the highest interest-rate sensitivity?",
                 ["Long maturity, low coupon", "Short maturity, high coupon", "Long maturity, high coupon", "Short maturity, low coupon"], 0,
                 "Long maturity and low coupon push cash flows far into the future, which raises duration the most."),
        ], xp=30)

    c3 = _concept(m_id, 3,
        "Credit risk and spreads",
        "Explain default risk, ratings and yield spreads, and estimate expected loss.",
        "A government you can print money for is very unlikely to default. A company can fail. Credit risk is the chance you will not be paid in full, "
        "and investors demand extra yield, the credit spread, to take it.",
        "A bond has a 2% chance of default and would recover 40% if it did. The expected loss on ₹10 lakh is about ₹12,000.",
        ["Credit spread = yield on the bond − yield on a comparable government bond.",
         "Expected loss = probability of default × loss given default × exposure.",
         "Loss given default = 1 − recovery rate.",
         "Spreads widen when credit worries rise, which pushes prices down."],
        ["Treating a higher yield as free money without asking about the credit risk.",
         "Relying on a rating as a guarantee.",
         "Forgetting liquidity: some bonds are hard to sell."],
        [
            _intro("Why does she pay more?", "A company's bond offers 9.5% while a government bond offers 7.2%. The extra 2.3% is not a gift. It is the price of risk. The skill is working out whether it is enough."),
            _teach("Ratings, spreads and expected loss",
                   "Rating agencies grade borrowers from the top grades (AAA, AA) through to speculative or default grades. Higher-rated borrowers pay lower spreads. The credit spread is the extra yield above a similar-maturity government bond, and it compensates for expected default loss, for the uncertainty around that loss, and for lower liquidity. Expected loss = probability of default (PD) × loss given default (LGD) × exposure, where LGD = 1 − recovery rate. As a rough guide, the spread needed to cover expected loss alone is PD × LGD each year.",
                   ["Spread = bond yield − government yield", "Expected loss = PD × LGD × exposure", "LGD = 1 − recovery rate"]),
            _example("Expected loss on a corporate bond",
                     "An investor puts ₹10,00,000 into a corporate bond. Its estimated chance of default over the year is 2%, and if it defaults she expects to recover 40% of the money, so the loss given default is 60%. Expected loss = 0.02 × 0.60 × 10,00,000 = ₹12,000, or 1.2% of the investment. The bond's spread of 2.3% over government bonds covers that 1.2% and leaves 1.1% to compensate for uncertainty and low liquidity.",
                     "A spread has to cover expected losses before it pays you anything extra."),
            _flash("What is loss given default?", "The share of the exposure lost if the borrower defaults: 1 minus the recovery rate."),
            _choice("A government bond yields 7.2%. A corporate bond of similar maturity yields 9.5%. The corporate bond has a 2% default probability and a 40% recovery rate.",
                    "Does the extra yield look like a fair reward for the credit risk?",
                    [("No, the extra yield is just profit, since the company will probably pay", "bad",
                      "Most of the time it will pay, but part of the spread is the insurance premium for the rare default. Expected loss alone takes 1.2%.",
                      _outcome(("Spread over government bond", 2.3), ("Expected loss per year", 1.2), "That leaves about 1.1% for liquidity and uncertainty.")),
                     ("Yes, it covers the 1.2% expected loss and leaves about 1.1% for uncertainty and low liquidity", "good",
                      "Correct. The 2.3% spread more than covers expected loss. Whether 1.1% is enough extra pay depends on how uncertain the estimates are and how easily the bond can be sold.",
                      _outcome(("Spread over government bond", 2.3), ("Expected loss per year", 1.2), "A spread that only just covers expected loss would offer no real reward.")),
                     ("It cannot be judged without knowing the coupon", "bad",
                      "The yield and the default and recovery estimates are enough to compare the spread with the expected loss.")]),
            _teach("Spreads move with the mood",
                   "Credit spreads change over time. In a downturn, defaults look more likely and investors demand more compensation, so spreads widen, and the prices of corporate bonds fall even if no default occurs. When confidence returns, spreads narrow and prices rise. A bond can also be downgraded, which raises its required spread and lowers its price. This is why a corporate bond can lose value when the economy sours even if its coupons keep being paid, and why diversifying across many issuers matters.",
                   ["Wider spreads mean lower prices", "A downgrade can cut the price before any default", "Diversify across issuers"]),
            _choice("A rating agency downgrades a company's bond by one notch. The bond keeps paying its coupons on time and has not defaulted.",
                    "What usually happens to the bond's price?",
                    [("It falls, because the credit spread investors demand rises", "good",
                      "Correct. A downgrade signals higher risk, so investors demand a higher yield. A higher required yield means a lower price even though payments are on time."),
                     ("Nothing, since the company is still paying", "bad",
                      "The price reflects expectations of future risk, not only what has already been paid."),
                     ("It rises, because lower ratings mean higher coupons", "bad", "The coupon is fixed. A lower rating raises the required yield, which lowers the price.")]),
            _mcq("A borrower has a 4% probability of default and creditors would recover 25% in default. What is the expected loss on ₹5,00,000?",
                 ["₹5,000", "₹15,000", "₹20,000", "₹10,000"], 1,
                 "LGD = 1 − 0.25 = 0.75. Expected loss = 0.04 × 0.75 × 5,00,000 = ₹15,000."),
            _mcq("What is the credit spread?",
                 ["The yield on a bond minus the yield on a comparable government bond", "The difference between the bid and ask price", "The coupon rate minus the inflation rate", "The difference between short and long yields"], 0,
                 "A credit spread is the extra yield over a similar government bond that compensates for credit and liquidity risk."),
        ], xp=30)

    m["concepts"] = [c1, c2, c3]
    ch["modules"] = [m]
    return ch


# ---------------------------------------------------------------------------
# CHAPTER 3: EQUITY VALUATION
# ---------------------------------------------------------------------------

def equity_chapter(course_id):
    ch, m, m_id = _chapter(course_id, 3, "Equity Valuation",
                           "What is a share worth? Dividend models, price multiples and the drivers of profitability and growth.", "Valuing shares")

    c1 = _concept(m_id, 1,
        "The dividend discount model",
        "Value a share as the present value of its dividends and solve for the required return.",
        "A share is a claim on a company's future cash. The dividend discount model values it as the present value of all future dividends. "
        "If dividends grow at a steady rate forever, the formula collapses into one line.",
        "A share paid a ₹10 dividend, growing at 6%, with a required return of 11%, is worth about ₹212.",
        ["Gordon growth: V0 = D1 ÷ (r − g), where D1 = D0 × (1 + g).",
         "The model needs r to be greater than g.",
         "Required return r = D1 ÷ P0 + g.",
         "The value is very sensitive to r and g."],
        ["Using D0 instead of D1 in the formula.",
         "Letting g exceed r, which gives a nonsense answer.",
         "Treating the model output as exact when its inputs are estimates."],
        [
            _intro("Paying for a stream", "You buy a share and will receive dividends for years. What is the right price today? Only the present value of those payments can answer."),
            _teach("Gordon growth model",
                   "If a company pays a dividend D0 that grows at a constant rate g forever, and investors require a return r, the value today is V0 = D1 ÷ (r − g), where D1 = D0 × (1 + g) is next year's dividend. It works only when r > g. Rearranging gives the market-implied required return: r = D1 ÷ P0 + g, the dividend yield plus the growth rate. The model is most useful for stable, dividend-paying companies. Because r − g sits in the denominator, small changes in r or g can move the value a lot.",
                   ["V0 = D1 ÷ (r − g)", "D1 = D0 × (1 + g)", "r = D1 ÷ P0 + g"]),
            _example("A steady dividend payer",
                     "A company just paid a ₹10 dividend (D0). Dividends are expected to grow at 6% a year forever and investors require 11%. D1 = 10 × 1.06 = ₹10.60. V0 = 10.60 ÷ (0.11 − 0.06) = 10.60 ÷ 0.05 = ₹212. If investors instead required 12%, V0 = 10.60 ÷ 0.06 = ₹176.67, about 17% lower.",
                     "One percentage point in the required return moved the value by about 17%."),
            _flash("What is the Gordon growth formula?", "V0 = D1 ÷ (r − g)."),
            _choice("A share trades at ₹200 and is expected to pay a ₹12 dividend next year, growing at 5% a year indefinitely.",
                    "What return is the market implicitly requiring from this share?",
                    [("6%, the dividend yield only", "bad",
                      "The dividend yield (12 ÷ 200 = 6%) is only part of the return. The dividends also grow, and that growth is part of the return investors expect.",
                      _outcome(("Dividend yield", 6), ("Required return", 11), "r = 6% + 5% = 11%.")),
                     ("11%, which is the 6% dividend yield plus 5% growth", "good",
                      "Correct. r = D1 ÷ P0 + g = 12 ÷ 200 + 0.05 = 0.06 + 0.05 = 11%.",
                      _outcome(("Dividend yield", 6), ("Required return", 11), "Income plus growth makes up the total return.")),
                     ("5%, because that is the growth rate", "bad", "Growth alone is not the full return. Add the dividend yield.")]),
            _teach("Limits of the model",
                   "The constant-growth model cannot be used when a company pays no dividend, or when its growth is not steady. In those cases analysts use multi-stage models, with a high-growth period followed by a stable growth period, or value the company on free cash flow or multiples instead. The model also breaks down if the growth rate is close to or above the required return, since the denominator becomes tiny or negative. Always sanity check: the long-run growth rate of a company cannot sensibly exceed the growth of the economy forever.",
                   ["No dividends: use another method", "Growth must stay below the required return", "Long-run growth is capped by the economy's growth"]),
            _choice("An analyst values a young, fast-growing company that pays no dividend with the Gordon growth formula and gets a value of zero. She concludes the share is worthless.",
                    "What is wrong with the analysis?",
                    [("The formula needs a steady dividend. A non-dividend, fast-growth company needs a different model", "good",
                      "Correct. The zero came from the input, not the company. She should use a multi-stage model, free cash flow or a multiples approach."),
                     ("Nothing. A company with no dividends has no value", "bad",
                      "Many companies retain their profits to grow, and the value comes from their future cash flows, even if not paid out as dividends yet."),
                     ("The required return must be too high, so she should lower it to zero", "bad", "Setting r to zero makes no financial sense.")]),
            _mcq("A company just paid ₹5 and dividends will grow at 4% forever. The required return is 9%. What is the value per share (use D1)?",
                 ["₹55.56", "₹104.00", "₹100.00", "₹62.50"], 1,
                 "D1 = 5 × 1.04 = ₹5.20. V0 = 5.20 ÷ (0.09 − 0.04) = 5.20 ÷ 0.05 = ₹104.00."),
            _mcq("In the Gordon growth model, what must be true for the formula to work?",
                 ["The required return must be greater than the growth rate", "The growth rate must be greater than the required return", "The dividend must be zero", "The share price must be below par"], 0,
                 "If g is not below r, the denominator r − g is zero or negative and the value is meaningless."),
        ], xp=30)

    c2 = _concept(m_id, 2,
        "Price multiples: P/E and friends",
        "Use P/E, earnings yield and PEG to compare shares, and know when multiples mislead.",
        "A price multiple compares a company's price with something it earns or owns. The most common is the price-to-earnings ratio, "
        "which says how many rupees investors pay for each rupee of annual profit.",
        "A share costs ₹300 and earns ₹20 per share, so its P/E is 15. If similar companies trade at 18 times earnings, it might be worth ₹360.",
        ["P/E = price ÷ earnings per share (EPS).",
         "Earnings yield = EPS ÷ price = 1 ÷ P/E.",
         "PEG = P/E ÷ growth rate (in percent).",
         "Compare against similar companies, and check the quality of earnings."],
        ["Comparing P/E across very different industries.",
         "Using a low P/E as proof of a bargain without asking why.",
         "Ignoring one-off items that distort EPS."],
        [
            _intro("What price per rupee of profit?", "One company trades at 15 times earnings, another at 30. Is the second one twice as expensive, or twice as good? Multiples are shorthand for that question."),
            _teach("P/E, earnings yield and PEG",
                   "P/E = price ÷ EPS. The inverse, EPS ÷ price, is the earnings yield, a return-like number you can compare with bond yields. A trailing P/E uses the last 12 months of EPS and a forward P/E uses expected EPS. Comparable-company valuation applies a peer P/E to the target's EPS: implied value = peer P/E × EPS. The PEG ratio, P/E ÷ expected growth rate (in percent), adjusts for growth, with lower being cheaper. Other common multiples are price-to-book (P/B) and EV/EBITDA.",
                   ["P/E = price ÷ EPS", "Earnings yield = 1 ÷ P/E", "PEG = P/E ÷ growth (%)", "Implied value = peer multiple × company metric"]),
            _example("Valuing with a peer multiple",
                     "A share trades at ₹300 and earned ₹20 per share, so its P/E is 300 ÷ 20 = 15. Its earnings yield is 20 ÷ 300 = 6.67%. Similar companies trade at a median P/E of 18. Applying 18 to its EPS gives an implied value of 18 × 20 = ₹360, which suggests the share could be undervalued, if the peers are truly comparable.",
                     "Multiples are only as good as the comparison group."),
            _flash("How do you turn P/E into an earnings yield?", "Earnings yield = 1 ÷ P/E (EPS ÷ price)."),
            _choice("Company A has a P/E of 15 and expects earnings to grow 12% a year. Company B has a P/E of 20 and expects earnings to grow 25% a year.",
                    "Which looks cheaper once growth is taken into account?",
                    [("Company A, because its P/E of 15 is lower", "bad",
                      "A lower P/E is not automatically cheaper. B's faster growth may justify its higher multiple.",
                      _outcome(("Company A PEG ×100", 125), ("Company B PEG ×100", 80), "A: 15 ÷ 12 = 1.25. B: 20 ÷ 25 = 0.80.")),
                     ("Company B, whose PEG of 0.80 is lower than A's 1.25", "good",
                      "Correct. PEG = P/E ÷ growth. A: 15 ÷ 12 = 1.25. B: 20 ÷ 25 = 0.80. Per unit of growth, B is cheaper, though growth forecasts are uncertain.",
                      _outcome(("Company A PEG ×100", 125), ("Company B PEG ×100", 80), "Lower PEG means you pay less for each point of growth.")),
                     ("They cannot be compared because their P/Es differ", "bad", "Adjusting for growth is exactly what the PEG is for.")]),
            _teach("When multiples mislead",
                   "A low P/E can signal a bargain, or a business in trouble whose earnings are about to fall. A high P/E can mean a great growth company, or just an expensive one. Cyclical companies look cheapest at their earnings peak and most expensive at their trough. One-off gains or losses can distort EPS, so analysts adjust for them. Comparing across industries or countries is risky because accounting, growth and risk differ. Multiples give a quick relative view, and should be combined with a deeper look at the business.",
                   ["Ask why the multiple is high or low", "Cyclical earnings distort P/E", "Adjust for one-off items", "Compare like with like"]),
            _choice("A steel company's P/E is only 5, lower than the market's 20. An investor says, 'It is clearly the cheapest share in the market.' Steel prices are at a record high, and have been very cyclical.",
                    "What is the best reaction?",
                    [("Buy, because 5 is far below 20", "bad",
                      "At a cyclical peak, earnings are unusually high, which makes the P/E look low. If steel prices fall, earnings may drop and the P/E may jump."),
                     ("Be careful. Peak earnings can make a cyclical P/E look cheap, so look at average earnings over a full cycle", "good",
                      "Correct. A low P/E at the top of the cycle often signals that the market expects earnings to fall. Normalised earnings give a fairer picture.")]),
            _mcq("A share priced at ₹240 has EPS of ₹16. What is its P/E, and what is its earnings yield?",
                 ["15 and 6.67%", "15 and 15%", "16 and 6.67%", "240 and 16%"], 0,
                 "P/E = 240 ÷ 16 = 15. Earnings yield = 16 ÷ 240 = 6.67%."),
            _mcq("A company has a P/E of 24 and expected earnings growth of 12% a year. What is its PEG ratio?",
                 ["0.5", "2.0", "12", "288"], 1,
                 "PEG = 24 ÷ 12 = 2.0."),
        ], xp=30)

    c3 = _concept(m_id, 3,
        "ROE, DuPont and sustainable growth",
        "Break return on equity into its drivers and estimate how fast a company can grow without raising new money.",
        "Return on equity (ROE) shows how much profit a company earns on its shareholders' money. The DuPont breakdown splits it into profit margin, "
        "asset efficiency and leverage, and ROE combined with the share of profit kept gives a growth rate.",
        "A company with an 8% margin, 1.5 asset turnover and 2.0 equity multiplier has an ROE of 24%. Keeping 60% of profits supports 14.4% growth.",
        ["ROE = net profit margin × asset turnover × equity multiplier.",
         "Sustainable growth rate g = ROE × retention ratio.",
         "Retention ratio = 1 − payout ratio.",
         "High ROE from leverage carries more risk than high ROE from margins."],
        ["Celebrating a high ROE that comes only from heavy debt.",
         "Forgetting that growth needs retained profit.",
         "Comparing ROE across companies without checking the drivers."],
        [
            _intro("Same ROE, different business", "Two companies both earn 24% on equity. One sells luxury goods with fat margins. The other is a thinly capitalised distributor loaded with debt. Which would you rather own? DuPont tells you why they differ."),
            _teach("The DuPont breakdown",
                   "ROE = net income ÷ equity. DuPont splits it into three parts: ROE = net profit margin (net income ÷ sales) × asset turnover (sales ÷ assets) × equity multiplier (assets ÷ equity). Margin shows profitability, turnover shows efficiency, and the equity multiplier shows leverage. Two companies with the same ROE can have very different risk. A company that gets its ROE from high leverage is more fragile than one that earns it from margins and efficiency.",
                   ["ROE = margin × turnover × leverage", "Margin: profitability", "Turnover: efficiency", "Equity multiplier: leverage"]),
            _example("Breaking down a 24% ROE",
                     "A company earns 8% of sales as net profit, generates ₹1.50 of sales per ₹1 of assets and has assets worth twice its equity. ROE = 0.08 × 1.5 × 2.0 = 0.24, or 24%. If it keeps 60% of its profits and pays out 40%, its sustainable growth rate is g = ROE × retention = 0.24 × 0.60 = 14.4%.",
                     "The growth a company can fund from its own profits is ROE multiplied by the share it retains."),
            _flash("What is the sustainable growth rate?", "ROE × retention ratio: the growth a company can fund from retained profit without new equity."),
            _choice("Company X has net margin 12%, asset turnover 1.0 and equity multiplier 1.5. Company Y has net margin 4%, asset turnover 1.5 and equity multiplier 3.0. Both have an ROE of 18%.",
                    "Which company's ROE is of higher quality?",
                    [("They are equal, since the ROE is the same", "bad",
                      "The same ROE can be built very differently, and the risk is not the same.",
                      _outcome(("Company X equity multiplier", 1.5), ("Company Y equity multiplier", 3.0), "Y's assets are 3 times its equity, against 1.5 times for X.")),
                     ("Company X, whose ROE comes mostly from profitability rather than from borrowing", "good",
                      "Correct. X: 0.12 × 1.0 × 1.5 = 18%. Y: 0.04 × 1.5 × 3.0 = 18%. Y's thin margin and heavy leverage make its ROE more fragile if sales dip or interest rates rise.",
                      _outcome(("Company X equity multiplier", 1.5), ("Company Y equity multiplier", 3.0), "Both are 18%, but Y carries far more financial risk.")),
                     ("Company Y, because it uses more leverage to boost returns", "bad",
                      "More leverage raises ROE when things go well but also magnifies losses when they do not.")]),
            _teach("Growth from retained profit",
                   "A company that pays out all its profit as dividends has no retained earnings to reinvest, so it can only grow by raising new money. The retention ratio is the share of profit kept: retention = 1 − payout ratio. The sustainable growth rate g = ROE × retention is the growth it can fund internally if its ROE and debt ratio stay steady. A high-ROE firm that retains a lot can grow quickly. The same g also plugs into the Gordon growth model, so ROE, payout and valuation are all connected.",
                   ["Retention = 1 − payout", "g = ROE × retention", "g can be used in the dividend discount model"]),
            _choice("A company has an ROE of 20% and pays out 70% of its earnings as dividends. Its CFO wants to double growth without raising new equity or debt, and without changing ROE.",
                    "What lever can she pull?",
                    [("Raise the retention ratio by paying out less in dividends", "good",
                      "Correct. g = ROE × retention. At 30% retention g = 6%. If she cuts the payout to 40%, retention is 60% and g doubles to 12%."),
                     ("Nothing, growth depends only on the economy", "bad",
                      "A company controls part of its own growth through how much profit it reinvests."),
                     ("Increase the payout ratio", "bad", "Paying out more leaves less profit to reinvest and lowers growth.")]),
            _mcq("A company has a net margin of 5%, asset turnover of 2.0 and an equity multiplier of 2.5. What is its ROE?",
                 ["10%", "25%", "12.5%", "50%"], 1,
                 "ROE = 0.05 × 2.0 × 2.5 = 0.25, or 25%."),
            _mcq("A company has an ROE of 15% and pays out 40% of its profit. What is its sustainable growth rate?",
                 ["6%", "9%", "15%", "25%"], 1,
                 "Retention = 1 − 0.40 = 0.60. g = 0.15 × 0.60 = 9%."),
        ], xp=30)

    m["concepts"] = [c1, c2, c3]
    ch["modules"] = [m]
    return ch


# ---------------------------------------------------------------------------
# CHAPTER 4: PORTFOLIO MANAGEMENT
# ---------------------------------------------------------------------------

def portfolio_chapter(course_id):
    ch, m, m_id = _chapter(course_id, 4, "Portfolio Management",
                           "Diversification, the capital asset pricing model, and building and rebalancing a portfolio for a real investor.", "Building portfolios")

    c1 = _concept(m_id, 1,
        "Portfolio return, risk and diversification",
        "Compute portfolio return and risk for two assets and explain why correlation drives diversification.",
        "A portfolio's return is the weighted average of its parts, but its risk is usually less than the weighted average. "
        "That free reduction in risk is called diversification, and the lower the correlation between assets, the bigger it is.",
        "A 60/40 mix of two assets can have lower risk than either the weighted average of their risks suggests.",
        ["Portfolio return = Σ weight × asset return.",
         "Risk is not a simple weighted average. It also depends on correlation.",
         "Correlation of +1 gives no diversification benefit; lower correlation gives more.",
         "Diversification reduces unsystematic risk, not market risk."],
        ["Averaging standard deviations to get portfolio risk.",
         "Believing more assets always means no risk.",
         "Ignoring that correlations rise in a crisis."],
        [
            _intro("The free lunch", "Economists rarely agree on anything, but most call diversification the closest thing to a free lunch. Let's see exactly how it works."),
            _teach("Two-asset portfolio",
                   "Portfolio expected return is the weighted average: E(Rp) = w1 × R1 + w2 × R2. Portfolio variance is σp² = w1²σ1² + w2²σ2² + 2 × w1 × w2 × ρ × σ1 × σ2, where ρ is the correlation between the two assets. If ρ = +1 the standard deviation is just the weighted average of the two. For any ρ below +1 the portfolio's standard deviation is smaller than that weighted average. The lower the correlation, the larger the reduction. With ρ = −1 and the right weights, risk can be eliminated entirely.",
                   ["E(Rp) = w1R1 + w2R2", "σp² = w1²σ1² + w2²σ2² + 2w1w2ρσ1σ2", "ρ < 1 means portfolio risk below the weighted average"]),
            _example("A 60/40 portfolio",
                     "Asset 1 returns 12% with a standard deviation of 20%. Asset 2 returns 6% with a standard deviation of 10%. A 60/40 portfolio has an expected return of 0.6 × 12 + 0.4 × 6 = 9.6%. If the correlation is +1, risk is 0.6 × 20 + 0.4 × 10 = 16%. If the correlation is 0.3, variance = 0.36 × 0.04 + 0.16 × 0.01 + 2 × 0.6 × 0.4 × 0.3 × 0.2 × 0.1 = 0.01888, so the standard deviation is 13.74%. At zero correlation it is 12.65%.",
                     "The same return, with lower risk, only because the assets do not move in lockstep."),
            _flash("What happens to portfolio risk if two assets are perfectly correlated (+1)?", "There is no diversification benefit. Portfolio risk is the weighted average of the two risks."),
            _choice("An investor holds only Asset 1 (return 12%, risk 20%). A friend suggests moving 40% of the money into Asset 2 (return 6%, risk 10%), with a correlation of 0.3 between them.",
                    "What happens to portfolio risk compared with the weighted average of 16%?",
                    [("It stays at 16%, because risk always averages", "bad",
                      "Risk averages only if the assets are perfectly correlated. With a correlation of 0.3 the assets partly offset each other.",
                      _outcome(("Weighted average of risks", 16), ("Actual portfolio risk", 13.74), "Standard deviation falls to about 13.74%.")),
                     ("It falls to about 13.7%, below the weighted average, because the assets do not move together", "good",
                      "Correct. With ρ = 0.3 the portfolio standard deviation is about 13.74%. The investor gives up some expected return (12% to 9.6%) but cuts risk by more than the weighted average suggests.",
                      _outcome(("Weighted average of risks", 16), ("Actual portfolio risk", 13.74), "A portion of each asset's swings cancels out.")),
                     ("It rises, because adding any asset adds risk", "bad", "Adding a partly uncorrelated asset can lower overall risk.")]),
            _teach("What diversification cannot remove",
                   "Total risk splits into systematic risk, which affects the whole market (recessions, interest rates, wars), and unsystematic risk, which is specific to one company or industry (a strike, a product recall). Adding many different assets removes most unsystematic risk, because company-specific events tend to cancel out. Systematic risk remains, because it hits everything at once. That is why investors are compensated only for bearing systematic risk. In a severe crisis, correlations between assets often jump towards one, so diversification helps less exactly when you most want it.",
                   ["Unsystematic risk: diversifiable", "Systematic risk: not diversifiable", "Correlations rise in crises"]),
            _choice("An investor owns shares of five banks and says, 'I am well diversified, I own five different companies.'",
                    "What is the best response?",
                    [("She still faces mostly the same industry and interest-rate risks, so she is less diversified than she thinks", "good",
                      "Correct. Five banks tend to move together, so their correlation is high. True diversification needs assets across different industries and asset classes."),
                     ("Yes, five companies means all risk is gone", "bad", "Some risk is removed, but market and industry risk remain."),
                     ("She should buy a sixth bank", "bad", "Another bank adds little diversification when the correlation to the others is high.")]),
            _mcq("Asset A returns 10% and Asset B returns 4%. What is the expected return of a portfolio with 50% in each?",
                 ["7%", "14%", "6%", "5%"], 0,
                 "0.5 × 10% + 0.5 × 4% = 5% + 2% = 7%."),
            _mcq("Two assets have a correlation of −0.5. Compared with perfect correlation, how is the portfolio risk?",
                 ["Lower", "Higher", "The same", "Always zero"], 0,
                 "The lower the correlation, the more the assets offset each other, which reduces portfolio risk."),
        ], xp=30)

    c2 = _concept(m_id, 2,
        "CAPM and beta",
        "Compute required return with the capital asset pricing model and interpret beta.",
        "The CAPM says a share's required return is the risk-free rate plus a reward for the market risk it carries. "
        "Beta measures how much a share tends to move when the market moves.",
        "With a 7% risk-free rate and a market return of 12%, a share with a beta of 1.2 has a required return of 13%.",
        ["Required return = Rf + β × (Rm − Rf).",
         "Beta of 1 moves with the market; above 1 amplifies; below 1 dampens.",
         "Rm − Rf is the market risk premium.",
         "If expected return is above the CAPM return, the share looks undervalued (positive alpha)."],
        ["Treating beta as total risk. It measures only market-related risk.",
         "Forgetting to subtract Rf in the premium.",
         "Treating CAPM inputs as precise."],
        [
            _intro("What return should you demand?", "Two shares both promise 13%. One barely moves when the market does, the other swings wildly. Should you be equally happy? CAPM says no, and shows why."),
            _teach("The CAPM and the security market line",
                   "CAPM: E(Ri) = Rf + βi × (E(Rm) − Rf). Rf is the risk-free rate, E(Rm) − Rf is the market risk premium, and beta βi measures the share's sensitivity to the market. A beta of 1 means the share moves with the market. A beta of 1.5 means it tends to move 1.5 times as much. Plotting required return against beta gives the security market line. A share whose expected return is above the line is undervalued, with positive alpha, and a share below the line is overvalued.",
                   ["E(R) = Rf + β × (Rm − Rf)", "β > 1: more volatile than the market", "Above the line: undervalued"]),
            _example("Required return on a share",
                     "The risk-free rate is 7% and the expected market return is 12%, so the market risk premium is 5%. A share with β = 1.2 has a required return of 7% + 1.2 × 5% = 13%. A defensive share with β = 0.8 requires 7% + 0.8 × 5% = 11%. A very aggressive share with β = 1.5 requires 14.5%.",
                     "The higher the beta, the higher the return investors demand."),
            _flash("What does a beta of 0.8 mean?", "The share tends to move about 0.8 times as much as the market, so it is less volatile than the market."),
            _choice("An analyst expects a share with β = 1.2 to return 14% next year. The risk-free rate is 7% and the market return is expected to be 12%.",
                    "Is the share attractively priced according to CAPM?",
                    [("No, because its beta is above 1", "bad",
                      "A high beta raises the required return, but it is not a reason to reject a share. Compare the expected return with the required return.",
                      _outcome(("Required return (CAPM)", 13), ("Expected return", 14), "The expected return is 1 percentage point above the required return.")),
                     ("Yes. CAPM requires 13%, and 14% is expected, so alpha is +1%: it looks undervalued", "good",
                      "Correct. Required = 7% + 1.2 × 5% = 13%. Expected 14% is above that, giving a positive alpha of 1 percentage point.",
                      _outcome(("Required return (CAPM)", 13), ("Expected return", 14), "It plots above the security market line.")),
                     ("It cannot be judged without knowing the share's price", "bad", "Comparing expected and required returns is enough for this question.")]),
            _teach("What beta does and does not tell you",
                   "Beta captures only systematic risk, the part tied to the market. A share can have a low beta and still be very risky on its own, for example a small company with a single product. Beta is estimated from past data, so it changes over time and with the choice of market index and period. CAPM also assumes investors hold diversified portfolios, which is why unsystematic risk earns no reward. Despite its limits, CAPM remains the standard way to set a required return for valuations.",
                   ["Beta = market risk only", "Estimated from history, so it can shift", "CAPM assumes diversified investors"]),
            _choice("A small company's share has a beta of 0.6, but its entire business depends on one customer. An investor says, 'A beta of 0.6 means this is a very safe share.'",
                    "What is the flaw in that statement?",
                    [("Beta measures only market-related risk, so the share can still carry large company-specific risk", "good",
                      "Correct. A single-customer business could collapse for reasons unrelated to the market. Beta does not capture that kind of risk."),
                     ("None, beta is a full measure of risk", "bad", "Beta measures sensitivity to the market, not total risk."),
                     ("The investor should multiply the beta by the risk-free rate", "bad", "That calculation has no meaning.")]),
            _mcq("The risk-free rate is 6% and the market return is 11%. What is the CAPM required return for a share with a beta of 1.4?",
                 ["13.0%", "15.4%", "7.0%", "12.5%"], 0,
                 "6% + 1.4 × (11% − 6%) = 6% + 7% = 13.0%."),
            _mcq("A share has a beta of 0.5. If the market rises 10%, what move would you roughly expect?",
                 ["About 5%", "About 10%", "About 20%", "About −5%"], 0,
                 "A beta of 0.5 means the share tends to move half as much as the market, so about 5%."),
        ], xp=30)

    c3 = _concept(m_id, 3,
        "Asset allocation and rebalancing",
        "Match a portfolio to an investor's objectives and constraints, and rebalance back to target weights.",
        "A portfolio should start from the investor, not the market. A written investment policy statement lists return goals, risk tolerance and constraints, "
        "and sets target weights. Over time markets move the weights, and rebalancing brings them back.",
        "A 60/40 portfolio of ₹10 lakh grows to 63% in equity after a good year. Rebalancing sells about ₹36,000 of equity to return to 60%.",
        ["Investment policy statement: objectives (return, risk) and constraints (time horizon, liquidity, taxes, legal, unique needs).",
         "Risk tolerance = ability to take risk + willingness to take risk. Use the lower of the two.",
         "Rebalancing sells what has grown and buys what has lagged, restoring target weights.",
         "Asset allocation is the main driver of a portfolio's risk."],
        ["Choosing assets before knowing the investor's needs.",
         "Letting winners run until the portfolio is far riskier than intended.",
         "Basing allocation on willingness alone when ability is low."],
        [
            _intro("Start with the person", "A 25-year-old saving for retirement and a 62-year-old about to retire could both ask, 'Where should I invest?' The right answer is very different, and it starts with their situation."),
            _teach("Objectives and constraints",
                   "An investment policy statement (IPS) records what the investor wants and the limits they face. Objectives: the return needed and the risk they can and will accept. Constraints: time horizon, liquidity needs, taxes, legal or regulatory limits, and unique circumstances such as ethical preferences. Risk tolerance has two parts. Ability to take risk depends on wealth, income, horizon and obligations. Willingness depends on attitude and temperament. When they differ, the investor should be guided by the lower of the two. A young person with steady income has high ability. A person who needs the money next year has low ability, no matter how brave they feel.",
                   ["IPS: objectives + constraints", "Ability vs willingness to take risk", "Use the lower of the two"]),
            _example("Two investors",
                     "Aisha is 25, has a stable job, no dependants and is saving for retirement 35 years away. She has high ability to take risk and says she is comfortable with market swings, so an equity-heavy allocation fits. Raj is 62, retiring in a year, and needs the money to pay living costs. His ability is low even though he says he likes risk. His allocation should be much more conservative.",
                     "Allocation follows the investor's situation, not the latest hot asset."),
            _flash("When ability and willingness to take risk differ, which should guide the allocation?", "The lower of the two."),
            _choice("Raj, 62, retires next year and needs his savings to pay for living costs. He tells his adviser, 'I am a risk-taker and I want to put 90% in equities for higher returns.'",
                    "What should the adviser conclude?",
                    [("Follow his wishes, because he is willing to take risk", "bad",
                      "Willingness is only half the picture. With a one-year horizon and a need for income, his ability to absorb a large loss is low."),
                     ("His ability to take risk is low despite his willingness, so the allocation should be more conservative", "good",
                      "Correct. A big equity loss just before retirement could force him to change his lifestyle. The lower of ability and willingness should guide the plan."),
                     ("Put everything in cash, because older people should never own equities", "bad", "A blanket rule ignores that he may still need growth over a long retirement. The answer is a balanced, not an extreme, mix.")]),
            _teach("Rebalancing",
                   "Markets move portfolios away from their targets. If equities rise faster than bonds, the portfolio becomes riskier than planned. Rebalancing sells some of what has grown and buys what has lagged to return to the target weights. It can be done on a calendar schedule, or when weights drift beyond a set band, such as 5 percentage points. Rebalancing controls risk, but it has costs: transaction costs and, in a taxable account, tax on gains. Many investors rebalance using new contributions to avoid selling.",
                   ["Calendar or threshold-based", "Restores the intended risk level", "Costs: transaction fees and tax"]),
            _choice("A ₹10,00,000 portfolio starts 60% equity and 40% bonds. After a year equity is up 20% and bonds are up 5%. The target is still 60/40.",
                    "What should the investor do to rebalance?",
                    [("Nothing, because both assets made money", "bad",
                      "Even though both gained, the mix has drifted. Equity is now about 63% of the portfolio, so the portfolio is riskier than intended.",
                      _outcome(("Equity weight before rebalancing (%)", 63.2), ("Target equity weight (%)", 60), "Equity: ₹7,20,000. Bonds: ₹4,20,000. Total: ₹11,40,000.")),
                     ("Sell about ₹36,000 of equity and buy bonds to get back to 60/40", "good",
                      "Correct. Equity is ₹7,20,000 and bonds ₹4,20,000, total ₹11,40,000. A 60% target is ₹6,84,000 in equity, so she sells ₹36,000 of equity and buys ₹36,000 of bonds.",
                      _outcome(("Equity weight before rebalancing (%)", 63.2), ("Target equity weight (%)", 60), "After selling ₹36,000: equity ₹6,84,000 and bonds ₹4,56,000.")),
                     ("Buy more equity, since it is performing best", "bad", "That would push the weights even further from the plan and raise risk.")]),
            _mcq("Which of these is a constraint in an investment policy statement?",
                 ["Time horizon", "Required return", "Risk tolerance", "Expected return of the market"], 0,
                 "Time horizon, liquidity, taxes, legal factors and unique circumstances are constraints. Return and risk tolerance are objectives."),
            _mcq("A ₹5,00,000 portfolio is targeted 50/50. Equity grows to ₹3,00,000 and bonds to ₹2,00,000. How much equity must be sold to return to 50/50?",
                 ["₹25,000", "₹50,000", "₹1,00,000", "₹5,000"], 1,
                 "Total = ₹5,00,000, so the equity target is ₹2,50,000. Equity is ₹3,00,000, so sell ₹50,000."),
        ], xp=30)

    m["concepts"] = [c1, c2, c3]
    ch["modules"] = [m]
    return ch
